#pragma once

#include <stdint.h>

// SIMULATED driving scenarios for the accident-detection replay harness.
// *** Every sample is generated by software. None of it is real sensor or vehicle data. ***
// The noise levels and impact shapes are assumptions to exercise the logic, not measurements.
// Vehicle frame: x forward, y left, z up. At rest az = 1 g.
// Sample rate 50 Hz (PLACEHOLDER). GPS speed updates once per second.

struct SimSample {
  uint32_t tMs;
  float ax, ay, az;      // g
  float gx, gy, gz;      // degrees per second
  int   speedState;      // 0 = no GPS update this sample, 1 = valid speed update, 2 = GPS unavailable
  float speedKmh;        // meaningful when speedState == 1
};

struct ScenarioInfo {
  const char* name;
  const char* description;
  bool ideal;            // would a good detector confirm an accident here? (judgement for the simulated case)
  int  expCandidates;    // documented behaviour with the default (jerk off) configuration
  int  expConfirmed;
  int  expCandidatesJerk;// documented candidates when jerk triggering is enabled
};

int scenarioCount();
const ScenarioInfo& scenarioInfo(int index);

// Streams the samples of one scenario to the callback (no large buffers needed).
void generateScenario(int index, void (*onSample)(const SimSample&, void*), void* ctx);
